"""Self-contained architecture/tradeoff review with actual tool receipts."""
import html
import json


def render(report: dict) -> str:
    has_replay = any('replay' in row for row in report['results'])
    explorer = '''<section id="explorer"><div class="eyebrow">CROSSHAIR / ПРОВЕРКА НА КОДЕ ATHENA</div>
<h2>Как ошибка меняет вывод о требовании</h2>
<p>Выбери реализацию и вход. Таблица получена выполнением четырёх комбинаций на зафиксированной копии функции. Отдельно показано, что обнаружил CrossHair.</p>
<div class="controls"><label>Реализация <select id="case-choice"></select></label></div>
<p id="case-explanation"></p><div id="case-status" class="boundary" aria-live="polite"></div>
<div class="replay-grid"><div class="card"><b>Свидетельства на входе</b><div id="replay-inputs" class="probe-grid"></div><small>Нажми комбинацию, чтобы увидеть её результат.</small></div>
<div class="card"><b>Ожидается → получено</b><p id="replay-answer" aria-live="polite"></p><p id="replay-meaning"></p></div></div>
<div class="scroll"><table><thead><tr><th>Есть поддержка</th><th>Есть опровержение</th><th>Ожидается</th><th>Получено</th><th>Сравнение</th></tr></thead><tbody id="replay-table"></tbody></table></div>
<details open><summary>Что сообщил CrossHair для выбранного случая</summary><pre id="case-output"></pre></details>
<p class="muted">Три ошибки внесены намеренно в копии кода. Этот опыт проверяет чувствительность контракта для одной функции; он не измеряет надёжность всего проекта.</p></section>''' if has_replay else ''
    scope = html.escape(report.get('provenance', {}).get('scope',
        'Намеренно слабое постусловие и невозможное предусловие включены как контрольные ловушки. Их успешная верификация демонстрирует границу формальных методов.'))
    provenance = '<details><summary>Происхождение исходников и границы прогона</summary><pre>' + html.escape(json.dumps(
        report.get('provenance', report.get('limitations', [])), ensure_ascii=False, indent=2)) + '</pre></details>'
    rows = []
    for row in report['results']:
        cells = (row['id'], row['engine'], row['subject_kind'], row['state'], row['scope'], row['elapsed_seconds'])
        rows.append('<tr>' + ''.join('<td>' + html.escape(str(v)) + '</td>' for v in cells) + '</tr>')
    payload = json.dumps(report, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return '''<!doctype html><html lang="ru"><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><title>Athena · проверяемый замысел</title>
<style>
:root{color-scheme:dark;--bg:#0b1220;--card:#141f32;--line:#2a3a52;--muted:#b2bfd3;--accent:#67dbc4}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:#edf3fd;font:16px/1.6 system-ui}main{max-width:1260px;margin:auto;padding:40px 24px}header{padding:24px 0 36px}h1{font-size:clamp(32px,5vw,58px);line-height:1.12;margin:12px 0}h2{margin-top:46px}p{max-width:950px}.eyebrow{color:var(--accent);letter-spacing:2px;font-size:12px}small,.muted{color:var(--muted)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:22px}.card b{display:block;font-size:19px}.arrow{text-align:center;color:var(--accent);padding:12px}.boundary{border-left:4px solid #ffc873;padding:12px 20px;background:#252235;border-radius:8px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}td,th{padding:12px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}th{color:var(--accent)}button,select{background:#20334e;border:1px solid #466180;color:white;border-radius:8px;padding:10px;font:inherit;cursor:pointer}button.active{border-color:var(--accent)}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#080e18;padding:18px;border-radius:12px;font-size:13px}a{color:#83c6ff}.pill{display:inline-block;padding:4px 9px;border:1px solid var(--line);border-radius:20px;font-size:12px}.trade{margin-top:15px;min-height:110px}.controls{display:flex;gap:10px;flex-wrap:wrap}details{margin:15px 0}@media(max-width:760px){.grid{grid-template-columns:1fr}main{padding:20px 14px}td,th{font-size:13px}}
.replay-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:20px 0}.replay-grid>.card{min-width:0}.probe-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}.controls label{min-width:0;max-width:100%}select{max-width:100%}.good{color:#67dbc4}.bad{color:#ffad9f}#replay-answer{font-size:22px;font-weight:650}#case-status{margin-top:15px}@media(max-width:760px){.replay-grid{grid-template-columns:1fr}}
</style><main>
<header><div class="eyebrow">ATHENA / SYSTEM DESIGN / 29 OCT 2026</div><h1>Что выполнено.<br>Чем подтверждено.<br>Где остаётся сомнение.</h1><p class="muted">Предложение архитектуры и исполняемый пилот. Реальные результаты инструментов ниже; не оценка надёжности всего фрейма.</p><span class="pill">Локальный прототип</span> <span class="pill">Без общей оценки «процента истины»</span></header>
<div class="boundary"><b>Замысел пользователя ≠ формальная спецификация ≠ реализация.</b> Доказательство свойства модели не доказывает соответствие отдельного Python-кода этой модели и не подтверждает полноту замысла.</div>
''' + explorer + '''
<h2>Поток доказательств</h2>
<div class="grid"><div class="card"><b>01 · Замысел пользователя</b>Примеры, ограничения, недопустимое поведение и открытые вопросы. Авторитет: пользователь и предметная область.</div><div class="card"><b>02 · Требования и свойства</b>Постусловия, предусловия, область действия. Ревью перевода замысла в формальную запись; проверка достижимости входов.</div><div class="card"><b>03 · Исполняемый субъект</b>Код Python или модуль Dafny. Модель помечается отдельно; связь с рабочим кодом требует собственных оснований.</div></div>
<div class="arrow">↓ явная привязка требования, свойств и входных файлов ↓</div>
<div class="grid"><div class="card"><b>Тесты + мутации</b>Примеры, свойства, допустимые альтернативы, активированные дефекты. Показывают чувствительность проверок в выбранной области.</div><div class="card"><b>CrossHair</b>Ищет контрпримеры Python-контрактам. Не нашёл ≠ доказал. Пустая проверка и ошибка инструмента дают UNKNOWN.</div><div class="card"><b>Dafny</b>Подтверждает записанные свойства в своей модели исполнения и при допущениях. Неудача доказательства ≠ найденный дефект.</div></div>
<div class="arrow">↓ команда · точные входы · сырой вывод · время · статус ↓</div>
<div class="card"><b>Запись результата → проверка актуальности → карта оснований</b><p>Реализованный адаптер сохраняет результат инструмента отдельно от прежней оценки выполнения требования. Следующая интеграция должна привязать свойства к каждому требованию и хранить возражения. При изменении входов результат перестаёт быть текущим.</p></div>
<h2>Компромиссы: выбери подход</h2>
<div class="controls"><button class="active" data-mode="layered">Подключаемые анализаторы</button><button data-mode="rewrite">Всё переписать на Dafny</button><button data-mode="tests">Только тесты и мутации</button></div><div id="trade" class="card trade"></div>
<div class="scroll"><table><tr><th>Выбор</th><th>Преимущество</th><th>Цена и граница</th></tr><tr><td>CrossHair для Python</td><td>Работа с существующим кодом; конкретные контрпримеры</td><td>Ограничения анализа, бюджет поиска, поддерживаемая семантика Python</td></tr><tr><td>Dafny для критического ядра</td><td>Доказательство явных свойств</td><td>Стоимость формализации, инварианты, доверенная база; связь с внешними компонентами</td></tr><tr><td>Dafny как модель</td><td>Можно исследовать алгоритм без переписывания продукта</td><td>Нужно отдельно проверить соответствие модели реальному коду</td></tr><tr><td>Мутации по подходу Stryker</td><td>Выявляют слабые проверки</td><td>Эквивалентные мутанты и стоимость повторных запусков; не доказывают смысл требований</td></tr></table></div>
<h2>Реальные наблюдения пилота</h2><p>''' + scope + ''' Сравнение результатов не является сравнением качества инструментов.</p>''' + provenance + '''
<div class="scroll"><table><tr><th>Случай</th><th>Движок</th><th>Субъект</th><th>Результат</th><th>Граница свойства</th><th>Секунды</th></tr>''' + ''.join(rows) + '''</table></div>
<h2>Открой свидетельство</h2><select id="receipt"></select><pre id="detail"></pre>
<h2>Что уже работает и что остаётся</h2><div class="grid"><div class="card"><b>Реализовано</b>Команда formal, два движка, проверка входных отпечатков до и после запуска, лимит времени, отдельные статусы, сырые результаты.</div><div class="card"><b>Следующий слой</b>Связь formal receipts с общей картой assurance, ревью формализации и предусловий, проверка модели против рабочей реализации.</div><div class="card"><b>Промышленный запуск</b>Изоляция недоверенного кода, фиксация полного окружения и транзитивных входов, структурированные результаты вместо текстового протокола, независимый корпус оценки.</div></div>
<p class="boundary">Локальный запуск не является песочницей. Хеши выявляют изменение объявленных файлов, но не доказывают полноту списка зависимостей и честность производителя. Успех Dafny не снимает эти допущения.</p>
<h2>Как оценивать следующий этап</h2><p>Заранее размеченный набор: корректный код, дефект, слабая спека, неоднозначное требование, недостижимые предусловия, тайм-аут, устаревший результат и расхождение модели с реализацией. Отдельно считать ложную поддержку, ложное опровержение и неизвестность. Авторские примеры пилота не дают независимой оценки точности.</p>
<p><a href="https://crosshair.readthedocs.io/en/latest/limitations.html">Ограничения CrossHair</a> · <a href="https://dafny.org/latest/DafnyRef/DafnyRef">Dafny Reference</a> · <a href="https://arxiv.org/abs/2405.15800">Assurance 2.0: возражения</a> · <a href="https://stryker-mutator.io/docs/General/faq/">Stryker: смысл метрик</a></p>
</main><script type="application/json" id="data">''' + payload + '''</script><script>
const report=JSON.parse(document.getElementById('data').textContent);
const choice=document.getElementById('receipt'), detail=document.getElementById('detail');
report.results.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.id+' · '+r.state;choice.append(o)});
function show(){detail.textContent=JSON.stringify(report.results[Number(choice.value)]||report,null,2)}choice.addEventListener('change',show);show();
const chooser=document.getElementById('case-choice');
if(chooser){
const cases=report.results.filter(r=>r.replay), yes=b=>b?'Да':'Нет';
const names={'production':'Исходный код Athena','valid-table-alternative':'Другая корректная реализация','conflict-on-either':'Ошибка: конфликт при одном свидетельстве','silence-is-support':'Ошибка: отсутствие свидетельств стало поддержкой','hide-conflict':'Ошибка: опровержение скрыто','missing-contract':'Контракт удалён'};
const explanations={'production':'Проверяем функцию combine из реального модуля assurance. Все четыре состояния должны оставаться различимыми.','valid-table-alternative':'Та же логика выражена таблицей. Проверка должна принимать разные корректные реализации.','conflict-on-either':'Условие AND заменено на OR: единственное свидетельство ошибочно превращается в конфликт.','silence-is-support':'UNKNOWN заменён на SUPPORTED: система начинает подтверждать требование без свидетельств.','hide-conflict':'CONFLICT заменён на SUPPORTED: одновременное опровержение теряется.','missing-contract':'Поведение кода прежнее, но формальные постусловия удалены. Совпадение примеров не создаёт контракт для CrossHair.'};
const meanings={'UNKNOWN':'Оснований нет. Требование остаётся неизвестным.','SUPPORTED':'Есть поддержка, опровержений нет. Вывод ограничен областью свидетельств.','CONTRADICTED':'Есть опровержение, поддержки нет.','CONFLICT':'Есть и поддержка, и опровержение. Противоречие нужно показать.'};
const states={'NO_COUNTEREXAMPLE':'CrossHair не нашёл контрпример. Это не общая гарантия правильности.','COUNTEREXAMPLE':'CrossHair нашёл контрпример к записанному постусловию.','UNKNOWN':'Проверка не дала оснований для вывода.'};
cases.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=names[r.id]||r.id;chooser.append(o)});
function selectInput(row){document.getElementById('replay-answer').textContent=row.expected+' → '+row.actual;document.getElementById('replay-answer').className=row.expected===row.actual?'good':'bad';document.getElementById('replay-meaning').textContent=(meanings[row.expected]||'')+(row.expected!==row.actual?' Реализация нарушает это правило.':'');document.querySelectorAll('#replay-inputs button').forEach(b=>b.classList.toggle('active',Number(b.dataset.index)===cases[Number(chooser.value)].replay.matrix.indexOf(row)))}
function selectCase(){const r=cases[Number(chooser.value)], matrix=r.replay.matrix;document.getElementById('case-explanation').textContent=explanations[r.id]||r.scope;document.getElementById('case-status').textContent=states[r.state]||r.state;document.getElementById('case-output').textContent=(r.stdout||'')+(r.stderr?'\\n'+r.stderr:'')||'Вывод инструмента отсутствует.';const inputs=document.getElementById('replay-inputs'), table=document.getElementById('replay-table');inputs.replaceChildren();table.replaceChildren();matrix.forEach((row,i)=>{const b=document.createElement('button');b.textContent='Поддержка: '+yes(row.support)+' · опровержение: '+yes(row.contradiction);b.dataset.index=i;b.addEventListener('click',()=>selectInput(row));inputs.append(b);const tr=document.createElement('tr');[yes(row.support),yes(row.contradiction),row.expected,row.actual,row.expected===row.actual?'Совпало':'Расхождение'].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});tr.className=row.expected===row.actual?'good':'bad';table.append(tr)});selectInput(matrix.find(x=>x.actual!==x.expected)||matrix[0]);const originalIndex=report.results.indexOf(r);choice.value=originalIndex;show()}
chooser.addEventListener('change',selectCase);selectCase();
}
const trades={layered:'Выбранный путь: общий формат свидетельств и подключаемые анализаторы. Даёт постепенное внедрение. Цена: разные уровни гарантий нельзя объединять в один PASS; нужны правила композиции и ревью связей.',rewrite:'Полный переход на Dafny даёт более однородную формальную базу. Цена: переписывание Python-инфраструктуры, формализация I/O и окружения. Ошибочный замысел всё равно можно точно реализовать и доказать. Для Athena сейчас чрезмерно.',tests:'Самый дешёвый вход и широкая совместимость. Хорош для реальных сценариев и регрессий. Цена: конечный набор наблюдений, зависимость от оракула, отсутствие общей гарантии для всех входов.'};
document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-mode]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('trade').textContent=trades[b.dataset.mode]}));document.getElementById('trade').textContent=trades.layered;
</script></html>'''
